/** 玩家数据接口 */
export interface PlayerData {
  id: string;
  username: string;
  global_name: string | null;
  avatar_url: string | null;
}

/** 获取玩家显示名 */
export function getDisplayName(player: PlayerData): string {
  return player.global_name || player.username;
}

/** 获取头像URL，无头像则返回null */
export function getAvatarUrl(player: PlayerData): string | null {
  return player.avatar_url;
}

/** 为玩家分配台词 */
export function assignLine(index: number): string {
  return DANMAKU_LINES[index % DANMAKU_LINES.length];
}
